// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(amount1 > 0 && amount1 <= type(uint128).max);
        vm.assume(amount2 > 0 && amount2 <= type(uint128).max);
        vm.assume(depositor != address(c));

        vm.deal(depositor, amount1 + amount2);

        vm.prank(depositor);
        c.addToBalance{value: amount1}();

        vm.prank(depositor);
        c.addToBalance{value: amount2}();

        uint256 finalBalance = c.getBalance(depositor);
        assertTrue(finalBalance >= amount1 + amount2);
    }
}
